# -*- coding: utf-8 -*-
"""Тестовые банковские выписки для ручной проверки пути в Esep.

Данные ВЫМЫШЛЕННЫЕ, но структура и формат — как у реальных банков КЗ.
Нужны, чтобы пройти путь «загрузил выписку → налог → счёт → акт»,
не имея на руках настоящих документов.

Сценарий во всех файлах одинаковый (ИП на упрощёнке, полугодие):
доходы от клиентов + типичные расходы. Итоги совпадают, чтобы можно было
сверить расчёт налога между форматами.

Запуск: py -3.14 test/fixtures/_build_statements.py
"""
import csv
import os

import xlsxwriter

HERE = os.path.dirname(os.path.abspath(__file__))

# ── Общий сценарий: (дата, описание, контрагент, сумма; + = доход) ──────────
OPS = [
    ("05.01.2026", "Оплата по счёту СЧ-001",        "ТОО Астана Трейд",      450000),
    ("12.01.2026", "Аренда офиса за январь",         "ТОО Бизнес Центр",     -120000),
    ("15.01.2026", "Оплата по счёту СЧ-002",        "ИП Сериков",            180000),
    ("20.01.2026", "Интернет и связь",               "АО Казахтелеком",        -9500),
    ("25.01.2026", "Зарплата сотруднику",            "Ахметова А.",          -200000),
    ("03.02.2026", "Оплата по счёту СЧ-003",        "ТОО Строй Групп",       620000),
    ("10.02.2026", "Аренда офиса за февраль",        "ТОО Бизнес Центр",     -120000),
    ("14.02.2026", "Канцтовары и расходники",        "ТОО Офис Плюс",         -34000),
    ("18.02.2026", "Оплата по счёту СЧ-004",        "ИП Нурланова",          250000),
    ("25.02.2026", "Зарплата сотруднику",            "Ахметова А.",          -200000),
    ("04.03.2026", "Оплата по счёту СЧ-005",        "ТОО Астана Трейд",      380000),
    ("11.03.2026", "Аренда офиса за март",           "ТОО Бизнес Центр",     -120000),
    ("16.03.2026", "Реклама в Instagram",            "Meta Platforms",        -75000),
    ("22.03.2026", "Оплата по счёту СЧ-006",        "ТОО Логистик КЗ",       540000),
    ("25.03.2026", "Зарплата сотруднику",            "Ахметова А.",          -200000),
    ("02.04.2026", "Оплата по счёту СЧ-007",        "ИП Сериков",            210000),
    ("09.04.2026", "Аренда офиса за апрель",         "ТОО Бизнес Центр",     -120000),
    ("17.04.2026", "Оплата по счёту СЧ-008",        "ТОО Строй Групп",       470000),
    ("25.04.2026", "Зарплата сотруднику",            "Ахметова А.",          -200000),
    ("06.05.2026", "Оплата по счёту СЧ-009",        "ТОО Медиа Груп",        330000),
    ("13.05.2026", "Аренда офиса за май",            "ТОО Бизнес Центр",     -120000),
    ("21.05.2026", "Оплата по счёту СЧ-010",        "ИП Нурланова",          290000),
    ("25.05.2026", "Зарплата сотруднику",            "Ахметова А.",          -200000),
    ("04.06.2026", "Оплата по счёту СЧ-011",        "ТОО Астана Трейд",      510000),
    ("11.06.2026", "Аренда офиса за июнь",           "ТОО Бизнес Центр",     -120000),
    ("19.06.2026", "Оплата по счёту СЧ-012",        "ТОО Логистик КЗ",       460000),
    ("25.06.2026", "Зарплата сотруднику",            "Ахметова А.",          -200000),
]

INCOME = sum(a for *_, a in OPS if a > 0)
EXPENSE = -sum(a for *_, a in OPS if a < 0)


def money(n):
    """1 234 567,89 — как в казахстанских выписках (пробел + запятая)."""
    return f"{abs(n):,.2f}".replace(",", " ").replace(".", ",")


# ── 1. Kaspi Business: колонки Дебет / Кредит, xlsx ────────────────────────
def kaspi_business():
    path = os.path.join(HERE, "vypiska_kaspi_business.xlsx")
    wb = xlsxwriter.Workbook(path)
    ws = wb.add_worksheet("Выписка")
    bold = wb.add_format({"bold": True})

    ws.write(0, 0, "Выписка по счёту", bold)
    ws.write(1, 0, "ИП ТЕСТОВЫЙ")
    ws.write(2, 0, "Период: 01.01.2026 - 30.06.2026")
    ws.write(3, 0, "Счёт: KZ123456789012345678")

    head = ["Дата", "Описание операции", "Контрагент", "Дебет", "Кредит"]
    for c, h in enumerate(head):
        ws.write(5, c, h, bold)

    r = 6
    for date, desc, cp, amt in OPS:
        ws.write(r, 0, date)
        ws.write(r, 1, desc)
        ws.write(r, 2, cp)
        if amt < 0:
            ws.write(r, 3, money(amt))
        else:
            ws.write(r, 4, money(amt))
        r += 1
    ws.set_column(0, 0, 12)
    ws.set_column(1, 2, 30)
    ws.set_column(3, 4, 16)
    wb.close()
    return path


# ── 2. Halyk: одна колонка «Сумма» со знаком, xlsx ─────────────────────────
def halyk():
    path = os.path.join(HERE, "vypiska_halyk.xlsx")
    wb = xlsxwriter.Workbook(path)
    ws = wb.add_worksheet("Statement")
    bold = wb.add_format({"bold": True})

    ws.write(0, 0, "Halyk Bank — выписка по текущему счёту", bold)
    ws.write(1, 0, "за период с 01.01.2026 по 30.06.2026")

    head = ["Дата операции", "Назначение платежа", "Получатель/Отправитель", "Сумма", "Валюта"]
    for c, h in enumerate(head):
        ws.write(3, c, h, bold)

    r = 4
    for date, desc, cp, amt in OPS:
        ws.write(r, 0, date)
        ws.write(r, 1, desc)
        ws.write(r, 2, cp)
        ws.write(r, 3, ("-" if amt < 0 else "") + money(amt))
        ws.write(r, 4, "KZT")
        r += 1
    ws.set_column(0, 0, 14)
    ws.set_column(1, 2, 32)
    ws.set_column(3, 4, 14)
    wb.close()
    return path


# ── 3. Jusan: только «Сумма списания» / «Сумма поступления», CSV ───────────
def jusan_csv():
    path = os.path.join(HERE, "vypiska_jusan.csv")
    with open(path, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f, delimiter=";")
        w.writerow(["Выписка по счёту ИП ТЕСТОВЫЙ"])
        w.writerow(["Период", "01.01.2026 - 30.06.2026"])
        w.writerow([])
        w.writerow(["Дата проводки", "Назначение", "Контрагент",
                    "Сумма списания", "Сумма поступления"])
        for date, desc, cp, amt in OPS:
            if amt < 0:
                w.writerow([date, desc, cp, money(amt), ""])
            else:
                w.writerow([date, desc, cp, "", money(amt)])
    return path


# ── 4. Неизвестный банк: нестандартные заголовки → ручная разметка ─────────
def unknown_bank_csv():
    path = os.path.join(HERE, "vypiska_neizvestnyy_bank.csv")
    with open(path, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f, delimiter=";")
        # заголовки, которых нет ни в одном словаре парсера —
        # проверяем экран «Укажите колонки»
        w.writerow(["Когда", "Кому/от кого", "За что", "Ушло", "Пришло"])
        for date, desc, cp, amt in OPS:
            if amt < 0:
                w.writerow([date, cp, desc, money(amt), ""])
            else:
                w.writerow([date, cp, desc, "", money(amt)])
    return path


if __name__ == "__main__":
    files = [kaspi_business(), halyk(), jusan_csv(), unknown_bank_csv()]
    print("Создано:")
    for p in files:
        print("  ", os.path.basename(p), f"({os.path.getsize(p)} байт)")
    print()
    print("Сценарий (одинаковый во всех файлах):")
    print(f"  операций:  {len(OPS)}")
    print(f"  доход:     {INCOME:,} тг".replace(",", " "))
    print(f"  расход:    {EXPENSE:,} тг".replace(",", " "))
    print(f"  прибыль:   {INCOME - EXPENSE:,} тг".replace(",", " "))
    print()
    print("Ожидаемый налог по упрощёнке (910), ставка 4% от ДОХОДА:")
    print(f"  {INCOME:,} x 4% = {int(INCOME * 0.04):,} тг".replace(",", " "))
    print("  (соцплатежи и вычеты считаются отдельно — сверять с приложением)")
